chain('x^6 - 64 = (x - 2)(x^2 + 2x + 4)(x + 2)(x^2 - 2x + 4)'); chain('x^2 - 17x + 60 = (x - 5)(x - 12)'); chain('x^2 + 4x - 45 = (x + 9)(x - 5)'); chain('2x^2 - 18 = 2(x - 3)(x + 3)'); chain('16p^4 - 81q^4 = (2p - 3q)(2p + 3q)(4p^2 + 9q^2)');
